{
  "apiVersion": 1,
  "type": "component.detail",
  "package": "@astryxdesign/core",
  "data": {
    "name": "ChatMessage",
    "subComponentOf": "Chat",
    "displayName": "Chat Message",
    "description": "Sender context wrapper: handles avatar, name, metadata, and alignment based on sender role.",
    "playground": {
      "defaults": {
        "sender": "assistant",
        "children": {
          "__element": "ChatMessageBubble",
          "children": "Here is the summary you asked for."
        },
        "avatar": {
          "__element": "Avatar",
          "props": {
            "name": "Astra",
            "size": "sm"
          }
        }
      },
      "wrapper": {
        "component": "Stack",
        "props": {
          "width": 480
        }
      }
    },
    "props": [
      {
        "name": "sender",
        "type": "'user' | 'assistant' | 'system'",
        "description": "Who sent this message: controls alignment and layout.",
        "required": true
      },
      {
        "name": "children",
        "type": "ReactNode",
        "description": "Free-form content: bubbles, asset lists, tool calls, images. Custom (non-bubble) children render flush with the message edge; wrap them in a ghost ChatMessageBubble to align them with the bubble text column.",
        "required": true,
        "slotElements": [
          {
            "__element": "ChatMessageBubble",
            "children": "Message text"
          }
        ]
      },
      {
        "name": "avatar",
        "type": "ReactNode",
        "description": "Avatar element rendered beside the message. Typically Avatar. `null`, booleans, and empty strings create no slot; any other content that renders nothing collapses its slot.",
        "slotElements": [
          {
            "__element": "Avatar",
            "props": {
              "name": "User",
              "size": "sm"
            }
          }
        ]
      },
      {
        "name": "name",
        "type": "ReactNode",
        "description": "Sender name rendered above the message body; it labels the message. `null`, booleans, and empty strings create no slot, and any other content that renders nothing collapses its slot; either way the message is labelled by the translated sender fallback. Use when the first child is raw content (not a bubble). If the first child is a bubble, put the name on the bubble's `name` prop instead."
      },
      {
        "name": "metadata",
        "type": "ReactNode",
        "description": "Metadata rendered below the message body. `null`, booleans, and empty strings create no slot; any other content that renders nothing collapses its slot. Use when the last child is raw content (not a bubble). If the last child is a bubble, put metadata on the bubble's `metadata` prop instead.",
        "slotElements": [
          {
            "__element": "Text",
            "props": {
              "type": "body"
            },
            "children": "Metadata"
          }
        ]
      },
      {
        "name": "density",
        "type": "'compact' | 'balanced' | 'spacious'",
        "description": "Visual density. Inherited from list context if not set.",
        "default": "'balanced'"
      }
    ],
    "package": "@astryxdesign/core",
    "import": "@astryxdesign/core/Chat",
    "sourceAvailable": true
  },
  "meta": {
    "answeredBy": {
      "cli": "0.7.12",
      "core": "0.7.12",
      "copy": "starting"
    }
  }
}
